#!/bin/bash
# .claude/hooks/verify-di-registration.sh
# Stop hook for implementer-tester (SubagentStop when declared in agent
# frontmatter). Checks that muuvie/lib/di/injection.config.dart is up to date.
#
# That file is generated by injectable_generator and gitignored (muuvie
# 3fc7f47), so it cannot be checked against source by name. Instead this hook
# blocks when the change set is non-empty and the config is
#   - missing while DI sources exist, or
#   - older than the newest file under muuvie/lib or muuvie/features carrying
#     @module / @injectable / @lazySingleton / @singleton (any case form).
# A stale config is what produces `GetIt: Object/factory not registered`.
#
# Usage: .claude/hooks/verify-di-registration.sh   (no arguments)
# validate-implementation.sh runs it after regenerate-generated-files.sh, so
# wire it on its own only if validate-implementation.sh is not wired: Stop
# hooks run in parallel and this one would race the regeneration.
# Exits 0 when stop_hook_active is set or nothing changed in muuvie/.

input=$(cat)
[ "$(printf '%s' "$input" | jq -r '.stop_hook_active // false' 2>/dev/null)" = true ] && exit 0
cwd=$(printf '%s' "$input" | jq -r '.cwd // empty' 2>/dev/null)
[ -d "$cwd" ] || cwd=$PWD
meta=$(git -C "$cwd" rev-parse --show-toplevel 2>/dev/null) || exit 0
while super=$(git -C "$meta" rev-parse --show-superproject-working-tree 2>/dev/null) && [ -n "$super" ]; do
  meta=$super
done
app="$meta/muuvie"
[ -f "$app/pubspec.yaml" ] || exit 0

# muuvie paths changed: uncommitted (incl. every untracked file) + commits
# ahead of origin/dev.
changed_files() {
  {
    git -C "$app" -c core.quotepath=off diff --name-only HEAD 2>/dev/null
    git -C "$app" -c core.quotepath=off ls-files --others --exclude-standard 2>/dev/null
    if git -C "$app" rev-parse -q --verify origin/dev >/dev/null 2>&1; then
      git -C "$app" -c core.quotepath=off diff --name-only origin/dev...HEAD 2>/dev/null
    fi
  } | sort -u
}
[ -n "$(changed_files)" ] || exit 0

DI_RE='@(module|injectable|lazySingleton|singleton|Injectable|LazySingleton|Singleton)([^A-Za-z0-9_]|$)'
config="$app/lib/di/injection.config.dart"

di_sources=$(grep -rlE --include='*.dart' --exclude-dir=.dart_tool --exclude-dir=build "$DI_RE" "$app/lib" "$app/features" 2>/dev/null |
  grep -vE '\.(g|gr|config)\.dart$')
[ -z "$di_sources" ] && exit 0

regen="Regenerate it from muuvie/: dart run build_runner build --delete-conflicting-outputs
(never edit it by hand; see the DI checklist in agents/implementer-tester.md)."

if [ ! -f "$config" ]; then
  echo "Blocked: muuvie/lib/di/injection.config.dart is missing, so GetIt has no registrations. $regen" >&2
  exit 2
fi

newer=""
while IFS= read -r source; do
  [ "$source" -nt "$config" ] && newer="$newer
  - ${source#"$app"/}"
done <<< "$di_sources"

if [ -n "$newer" ]; then
  echo "Blocked: muuvie/lib/di/injection.config.dart is older than these DI sources, so new registrations are missing:$newer
$regen" >&2
  exit 2
fi
exit 0
